    @staticmethod
    def sanitize_input(input_str: str) -> str:
        """Basic input sanitization"""
        # This is incomplete and doesn't prevent all XSS attacks
        replacements = {
            '<': '&lt;',
            '>': '&gt;',
            '"': '&quot;',
            "'": '&#x27;',
            '/': '&#x2F;'
